-- ----------------------------
-- Table structure for lawyers
-- ----------------------------
DROP TABLE IF EXISTS `lawyers`;
CREATE TABLE `lawyers`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '律师编号',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '律师名称',
  `avatar` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '律师头像',
  `email` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮箱',
  `level` int(11) NULL DEFAULT NULL COMMENT '律师等级[0:助理律师,1:四级律师,2:三级律师,3:二级律师,4:一级律师]',
  `info` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '简历',
  `certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证书',
  `age` int(11) NULL DEFAULT NULL COMMENT '年龄',
  `sex` int(11) NULL DEFAULT NULL COMMENT '性别[0:男,1:女]',
  `status` int(11) NULL DEFAULT NULL COMMENT '状态[0:审核中,1:审核通过,2:审核不通过]',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `password` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '密码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '律师信息' ROW_FORMAT = Dynamic;

