INSERT INTO `lawyers` VALUES (1, '黄律师', 'https://jmy-pic.baidu.com/0/pic/-877401569_3413834_1392032398.jpg', '10010@qq.com', 0, '刑事辩护、金融证券犯罪、经济犯罪、职务犯罪和走私犯罪辩护等刑事辩护、金融证券犯罪、经济犯罪、职务犯罪和走私犯罪辩护等刑事辩护、金融证券犯罪、经济犯罪、职务犯罪和走私犯罪辩护等刑事辩护、金融证券犯罪、经济犯罪、职务犯罪和走私犯罪辩护等刑事辩护、金融证券犯罪、经济犯罪、职务犯罪和走私犯罪辩护等刑事辩护、金融证券犯罪、经济犯罪、职务犯罪和走私犯罪辩护等', 'http://localhost:8092/Statute/89376b12-7ef7-4101-a854-f586218f905b.jpg', 28, 0, 1, '2024-05-08 15:54:09', '123456');
INSERT INTO `lawyers` VALUES (2, '杜律师', 'https://jmy-pic.baidu.com/0/pic/-2121242822_-1680428339_-1179204943.jpg', '10011@qq.com', 4, '高端婚姻家事律师，擅长处理重大、特大、疑难、涉外的婚姻、继承、析产等家事诉讼', 'http://localhost:8092/Statute/89376b12-7ef7-4101-a854-f586218f905b.jpg', 26, 0, 1, '2024-05-08 15:54:09', '123456');
INSERT INTO `lawyers` VALUES (3, '易律师', 'https://jmy-pic.baidu.com/0/pic/1636858435_-1431119487_780927394.png', '10012@qq.com', 1, '工程、房地产、企业股权和合规', 'http://localhost:8092/Statute/89376b12-7ef7-4101-a854-f586218f905b.jpg', 28, 0, 1, '2024-05-08 15:54:09', '123456');
INSERT INTO `lawyers` VALUES (4, '袁律师', '	https://jmy-pic.baidu.com/0/pic/1760520734_-768783950_-1174074068.jpg', '10086@qq.com', 3, '公司法律事务、合同诉讼仲裁、知识产权、企业融资并购与重组、土地、房地产法律事务、经济犯罪辩护', 'http://localhost:8092/Statute/89376b12-7ef7-4101-a854-f586218f905b.jpg', 32, 0, 1, '2024-05-08 15:54:09', '123456');
INSERT INTO `lawyers` VALUES (5, '阿周', 'http://localhost:8092/Statute/843e3557-7435-42d3-bad1-dfa263453c63.jpg', '1192705529@163.com', 4, '李华是一位资深律师，拥有超过十年的法律行业经验。她在著名的法学院完成了法学本科和硕士学位，并在国家司法考试中以优异的成绩获得了执业资格。李律师在处理复杂的商业诉讼、知识产权争议以及公司法和合同法问题方面尤为擅长。\n\n在她的职业生涯中，李华代表过多个知名企业和个人客户，成功解决了一系列高难度法律案件。她以其精湛的法律分析能力、严谨的工作态度和对客户利益的坚定维护而受到客户的高度评价。李律师还经常受邀参加各种法律研讨会和讲座，分享她的专业知识和实践经验。\n\n除了在法庭上的出色表现，李华还积极参与公益活动，为弱势群体提供法律援助。她坚信法律的力量应该用于正义和公平，这一信念贯穿了她的整个职业生涯。无论是在私人执业还是在公共服务领域，李律师都致力于推动法律的进步和社会的公正。\n\n作为一名律师，李华不仅具备深厚的法律知识和丰富的实战经验，还具有敏锐的商业洞察力和卓越的沟通能力。她能够迅速理解客户的核心需求，并提供切实可行的解决方案，这使得她成为法律领域内的杰出代表。', 'http://localhost:8092/Statute/e06456fa-904d-4aae-950e-b57caed2812e.png', 28, 0, 0, '2024-05-09 09:56:32', '123456');

-- ----------------------------
